EM = re.compile(r"(\*|_)([^\s*_][^*_]*?)\1")
AUTOLINK = re.compile(r"(?<![\w/])(https?://[^\s<]+?)(?=[,.;!?)<\s]|$)")


def render(blocks) -> str:
    out = "\n\n".join(render_block(b) for b in blocks)
    return out.rstrip() + "\n"


