        tag = "ol" if block.ordered else "ul"
        items = "\n".join(f"<li>{_render_item(li)}</li>" for li in block.items)
        return f"<{tag}>\n{items}\n</{tag}>"
    raise TypeError(f"unknown block: {block!r}")


